using System.Collections.ObjectModel;
using System.Threading.Tasks;
using Floworks.MAUI.Models;
using Floworks.MAUI.Models.UI;
using Floworks.MAUI.Services;
using ReactiveUI;

namespace ${Namespace};

public class ${ClassName}ViewModel : StandardTableViewModel<${ItemType}>
{
    public ${ClassName}ViewModel(IDatabaseService databaseService, INavigationService? navigationService = null)
        : base(databaseService, navigationService)
    {
        InitializeTableDefinitions();
        EmptyMessage = "Ni zapisov za prikaz.";
    }

    protected override void DefineFilters()
    {
        FilterDefinitions.Add(new FilterDefinition
        {
            Key = "search",
            Type = FilterType.TextSearch,
            Label = "Iskanje",
            Placeholder = "Iskanje...",
            WidthRequest = 200
        });
    }

    protected override void DefineColumns()
    {
        TableColumns.Add(new TableColumnDefinition { Key = "Id",   Header = "ID",    Width = 60,  IsSortable = true });
        TableColumns.Add(new TableColumnDefinition { Key = "Name", Header = "Naziv", Width = 200, IsSortable = true });
    }

    protected override void DefineActions()
    {
        ToolbarActions.Add(new ToolbarAction
        {
            Id = "add", Text = "Dodaj", Icon = "＋",
            Tooltip = "Dodaj zapis (Ctrl+N)",
            Command = AddCommand,
            BackgroundColor = Color.FromArgb("#2a6c5b"),
            SortOrder = 0
        });
        ToolbarActions.Add(new ToolbarAction
        {
            Id = "delete", Text = "Izbriši", Icon = "🗑",
            Tooltip = "Izbriši izbrani zapis (Del)",
            Command = DeleteCommand,
            BackgroundColor = Color.FromArgb("#8b1a1a"),
            SortOrder = 1
        });
    }

    protected override async Task LoadDataAsync()
    {
        IsLoading = true;
        try
        {
            var search = GetFilterString("search");
            var order  = GetOrderByClause();

            // TODO: zamenjaj z dejanskim API/DB klicem
            var sql = $"""
                SELECT * FROM ${ItemType}
                WHERE ($1 IS NULL OR name ILIKE '%' || $1 || '%')
                {order}
                LIMIT {PageSize} OFFSET {(CurrentPage - 1) * PageSize}
                """;

            var items = await _databaseService.QueryAsync<${ItemType}>(sql, search);
            Items = new System.Collections.ObjectModel.ObservableCollection<${ItemType}>(items);
            FilteredItems = Items;
        }
        finally { IsLoading = false; }
    }

    protected override async Task DeleteItemAsync(${ItemType} item)
    {
        // TODO: implementiraj brisanje
        await Task.CompletedTask;
    }
}

using Floworks.MAUI.ViewModels;
using ${Namespace};

namespace ${Namespace};

public partial class ${ClassName}Page : ContentView
{
    public ${ClassName}Page()
    {
        InitializeComponent();
    }

    public ${ClassName}Page(${ClassName}ViewModel viewModel) : this()
    {
        BindingContext = viewModel;
    }

    protected override void OnBindingContextChanged()
    {
        base.OnBindingContextChanged();
        if (BindingContext is ${ClassName}ViewModel vm)
            Loaded += async (_, _) => await vm.LoadDataCommand.ExecuteAsync(null);
    }
}

